export class ReplayFinishedEvent extends Event{static eventName="replayfinished";constructor(){super(ReplayFinishedEvent.eventName,{bubbles:!0,composed:!0})}}export class RecordingStateChangedEvent extends Event{recording;static eventName="recordingstatechanged";constructor(e){super(RecordingStateChangedEvent.eventName,{bubbles:!0,composed:!0}),this.recording=e}}